import{z as i,x as l,o as n,c as p,q as s,j as E,D as e,d as r,s as o,S as B}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Tanenbaum 现代操作系统","description":"","frontmatter":{"title":"Tanenbaum 现代操作系统","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tanenbaum-mos.md","filePath":"cs/tanenbaum-mos.md","lastUpdated":1791413859000}'),A={name:"cs/tanenbaum-mos.md"};function d(m,a,S,u,h,c){const t=l("Mermaid");return n(),p("div",null,[a[2]||(a[2]=s('<h1 id="tanenbaum-现代操作系统" tabindex="-1">Tanenbaum 现代操作系统 <a class="header-anchor" href="#tanenbaum-现代操作系统" aria-label="Permalink to &quot;Tanenbaum 现代操作系统&quot;">​</a></h1><div class="epigraph"><p>操作系统是资源与抽象的教材对象：进程、内存、文件、I/O；微内核与单体是实现对照，不是本栏另开的一课。</p><footer>—— Tanenbaum and Bos, Modern Operating Systems</footer></div><p><a href="/cs/dragon-book">上一课</a>附录对照了编译龙书。附录对照，不插入主干。本栏附录到此结束。主干已在<a href="/cs/dragon-book">内核与用户态</a>到<a href="/cs/vfs">VFS</a>、<a href="/cs/io-dma">I/O 与 DMA</a>里按映像、调度、同步、虚存、文件走过 OS；这里对照 <strong>MOS 教材的问题</strong>：如何把这些子系统收成可教的一本，并用 MINIX 一类系统当存在性证明。不重做 CFS 与 inode。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dijkstra 给出互斥规格；主干把它放进锁课。Tanenbaum 的缺口是整机教材：从中断到文件系统的工程地图，以及微内核辩论（消息换内核入口）。主干按树上课，不把 MINIX 源码当必读，也不把 Windows/Linux 型号审计插进主干——型号与实现审计是附录级，本篇只对照教材地图。</p><p><span class="marginnote">Bovet/Cesati、CSAPP、OSTEP 是另几本对照。主干用「内核是引用监视器 + 资源调度器」这一层，不绑死某一本书的章节号。</span></p><p><span class="marginnote">数字实例：Linux 内核里驱动代码占总行数一半以上——单体结构下这「一半」全都运行在最高特权；MINIX 3 则把驱动挪到用户态，一个坏驱动崩溃只需重启那一个进程，整机不必重启。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>教材分：进程与线程、调度、同步、死锁、虚存、文件、I/O、多处理。主干顺序与此相近，但把组成与体系结构的页表、TLB 放在 OS 之前讲硬件。MOS 常从 OS 视角再讲一遍分页；本栏不重复，OS 课只补<a href="/cs/demand-paging">按需调页</a>与替换。</p>',9)),(n(),E(B,null,{default:e(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOS%5B%22MOS%20%E5%9C%B0%E5%9B%BE%22%5D%20--%3E%20SUB%5B%22%E8%BF%9B%E7%A8%8B%20%2F%20%E5%86%85%E5%AD%98%20%2F%20%E6%96%87%E4%BB%B6%20%2F%20I%2FO%22%5D%0A%20%20SUB%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%20OS%20%E5%90%84%E8%AF%BE%22%5D%0A%20%20MOS%20--%3E%20MK%5B%22%E5%BE%AE%E5%86%85%E6%A0%B8%E5%AF%B9%E7%85%A7%3A%20%E4%B8%8D%E6%8F%92%E5%85%A5%E4%B8%BB%E5%B9%B2%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把 OS 写成抽象：进程是映像与调度单位，文件是字节流，VFS 是对象接口。主干已经这样命名。微内核把驱动放到用户态，用消息替代许多系统调用路径——主干<a href="/cs/syscall-path">系统调用路径</a>不改成消息课，附录只标明这是实现轴。安全课的隔离与沙箱假定这张地图已经存在。</p><p><span class="marginnote">术语翻译：微内核就是「把驱动、文件系统请出内核，只留调度、内存管理、IPC 三件最小心跳」，其余服务变成互相发消息的用户态进程。</span></p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3>',4)),(n(),E(B,null,{default:e(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20MONO%5B%22%E5%8D%95%E4%BD%93%E5%86%85%E6%A0%B8%22%5D%0A%20%20%20%20A%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%7C%22%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%7C%20K%5B%22%E5%86%85%E6%A0%B8%EF%BC%9A%E8%B0%83%E5%BA%A6%2B%E5%86%85%E5%AD%98%2B%E9%A9%B1%E5%8A%A8%E5%90%8C%E5%9D%80%22%5D%0A%20%20%20%20K%20--%3E%20H1%5B%22%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20end%0A%20%20subgraph%20MICRO%5B%22%E5%BE%AE%E5%86%85%E6%A0%B8%22%5D%0A%20%20%20%20B%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%7C%22IPC%20%E6%B6%88%E6%81%AF%22%7C%20S%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E9%A9%B1%E5%8A%A8%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20%20%20S%20--%3E%7C%22IPC%20%E5%9B%9E%E5%BA%94%22%7C%20B%0A%20%20%20%20S%20--%3E%7C%22%E7%89%B9%E6%9D%83%E6%93%8D%E4%BD%9C%22%7C%20M%5B%22%E5%BE%AE%E5%86%85%E6%A0%B8%EF%BC%9A%E4%BB%85%E8%B0%83%E5%BA%A6%2F%E5%86%85%E5%AD%98%2FIPC%22%5D%0A%20%20%20%20M%20--%3E%20H2%5B%22%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p><span class="marginnote">常见误区：初学者容易以为「微内核小，所以更快」。实际上一条设备请求在微内核里要经历多次 IPC 消息往返，开销常比单体里的一次函数调用高一个数量级——故障隔离是用通信开销换来的，MOS 把这场辩论当教材主线之一。</span></p><p>若把 MOS 插在编译与 OS 之间当「必读全书」，课序会变成教材目录。本栏 OS 第一课接运行时 GC，对象是内核边界。附录对照教材，结束文献序列：不再插入第五种子系统。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 MINIX 版权争论写成课文。也不要在附录里开容器编排。计算机栏主干已在<a href="/cs/to-systems-boundary">计算栈到此为止</a>封口；本附录是文献对照的最后一篇，不把读者送回比特课，只送回那张系统地图。</p><p>分布式 OS 与移动计算是 MOS 后段章节，本栏主干不收；需要的话属于另一棵树，不插在安全课之后当续篇。</p><p>对照结束应回到主干 OS 课与<a href="/cs/to-systems-boundary">计算栈到此为止</a>。文献序列在此终止，不把 MOS 后段章节续进主干。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>附录对照，不插入主干。</p></li><li><p>文献对照在此结束；主干封口仍是计算栈到此为止。</p></li><li><p>附录对照 Tanenbaum MOS：OS 子系统教材地图与微内核对照。</p></li><li><p>主干 OS 课已按映像到 VFS 取用；型号与源码审计不进主干。</p></li><li><p>文献对照序列在此结束；主干封口仍是 to-systems-boundary。</p></li><li><p>出处：Tanenbaum and Bos, <em>Modern Operating Systems</em>。</p></li></ul>',8))])}const C=i(A,[["render",d]]);export{b as __pageData,C as default};
